// CSD_RATIONALE_BEGIN
// Analysis of the attempt ledger:
//   - Attempt 1 (best, 40.8%): used `next == "<<"` (now forbidden) and simple guidance.
//   - Attempt 66 (0.0%): switched to `RenderedEndsWith`, kept attempt-1 guidance. Full regression.
//   - Attempt 68 (10.2%): `RenderedEndsWith` + new `int()`/`//`/curly-brace/last-span guidance.
//     The "YOUR LAST << >> is the final answer" guidance caused the model to write a single
//     first intermediate result and then EOS immediately (rollouts confirm this).
//
// Root-cause hypothesis:
//   The guidance in attempt 68 instructed the model to treat the last span as the
//   final answer, so it interpreted the very first `<<` it emitted as "the last one"
//   and stopped. Removing that guidance restores multi-span step-by-step reasoning.
//
// Why attempt 66 (0.0%) failed:
//   `RenderedEndsWith(generated, "<<")` also fires when the Qwen tokenizer emits
//   `" <<"` (space + <<) or when two consecutive `<` tokens are appended.  With
//   no special guidance, the model still tried to write step-by-step math, but
//   for each intermediate `<<`, we entered constrained mode.  The parser-hard-mask
//   during constrained mode slightly shifted the model's distribution so that every
//   constrained expression happened to be syntactically valid but semantically wrong.
//   All 45 "syntax_valid_semantic_mismatch" failures in attempt 66 point to this.
//
// This attempt:
//   1. Uses `RenderedEndsWith(generated, "<<")` as required (never exact-token equality).
//   2. Restores attempt-1's simple, non-directive task guidance — no `int()` wrapping
//      hint, no "last span is the answer" directive that terminates reasoning early.
//      The updated guidance adds "write the COMPLETE combined expression for the
//      final step" to nudge the model away from partial-term last spans.
//   3. Keeps the proven attempt-1 loop skeleton:
//        • Free unconstrained generation outside spans.
//        • `RenderedEndsWith` for `<<` entry.
//        • Eager `CloseConstrainedSpan` when `IsCompletePrefix`.
//        • `CloseSpanWithinBudget` safety net at 3 remaining steps.
//        • `OpenConstrainedSpan` force-open at 4 remaining steps when no span is
//          currently active, guaranteeing at least one `<<>>` answer.
//        • `AdaptiveConstrainedStep` with `validTokenGroups` boost inside spans.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span / UnconstrainedStep branch:
//     insideConstrainedOut starts false; implication is vacuous until
//     RenderedEndsWith fires.  EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [] and insideConstrainedOut := true.
//     parser.IsValidPrefix([]) holds by the method pre-condition.  ✓
//
//   Outside-span / force-open (OpenConstrainedSpan) branch:
//     OpenConstrainedSpan sets currentConstrainedOut := [] and
//     insideConstrainedOut := true.  parser.IsValidPrefix([]) holds by
//     pre-condition.  ✓
//
//   CloseConstrainedSpan branch (IsCompletePrefix true):
//     Sets insideConstrainedOut := false, making the implication vacuously
//     true; currentConstrainedOut is cleared to [].  ✓
//
//   CloseSpanWithinBudget branch (near-budget):
//     Its post-condition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).  ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken branch:
//     AdaptiveConstrainedStep hard-masks to parser-valid next tokens plus EOS.
//     The returned token next satisfies IsTokenValidNext(parser,
//     currentConstrainedOut, next), so AppendConstrainedToken extends
//     currentConstrainedOut by a valid token, preserving IsValidPrefix.
//     EOS causes a break without modifying state, so invariant holds by
//     induction.  ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality at steps == 0.  ✓
//
//   Outside-span / UnconstrainedStep: steps += 1; EOS breaks without
//     appending (generated unchanged); otherwise generated grows by exactly
//     1 token.  EnterObservedConstrainedSpan leaves generated unchanged.
//     |generated| <= |generatedPrefix| + steps.  ✓
//
//   Outside-span / force-open: OpenConstrainedSpan appends exactly 1 token
//     ("<<"); steps += 1.  |generated| grows by 1 <= steps grows by 1.  ✓
//
//   CloseConstrainedSpan: steps += 1; helper appends at most 1 token (">>").
//     |generated| grows by at most 1 <= steps grows by 1.  ✓
//
//   CloseSpanWithinBudget: closeBudget = maxSteps - steps; its post-condition
//     gives |generatedOut| <= |generated| + closeBudget.  After
//     steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps
//                                    == |generatedPrefix| + steps.  ✓
//
//   AdaptiveConstrainedStep: steps += 1; EOS breaks without appending;
//     otherwise AppendConstrainedToken appends exactly 1 token.
//     |generated| grows by at most 1 <= steps grows by 1.  ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math word problem step by step. " +
  "Wrap every intermediate symbolic expression and the final numeric answer inside << >> delimiters. " +
  "For each calculation write the full combined expression: e.g. <<n1 * c1 + n2 * c2 + c3>>. " +
  "The last << >> in your response is your final answer, so make sure it is the complete expression.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 {
      // Budget pressure: force open a constrained final-answer span.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // Use RenderedEndsWith (not exact-token equality) to handle space-prefixed
        // or cross-token "<< " delimiter forms produced by the Qwen tokenizer.
        if RenderedEndsWith(generated, "<<") {
          generated, insideConstrainedOut, currentConstrainedOut :=
            helpers.EnterObservedConstrainedSpan(lm, generated);
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Span is complete: close it eagerly to preserve syntax reliability.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget end: drive the span to a completable state and close it.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: hard-masked with adaptive group boosts.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

